// Game art — two routes, full catalog (Option A PNG default, Option B soft
// SVG via Settings → LOOK & FEEL → GAME ART). Variants + same-family games
// resolve through ART_ALIAS (mirrors the icon fallback); <GameArt/> returns
// null for unknown types so callers need no per-game branches.
//
// Option A: static PNGs in public/game-art/ (256×256, fixed bright palette,
// generated by scripts/make-game-art.mjs — `npm run art`). Punchy, identical
// in every theme, ~3 KB each.
// Option B: soft theme-aware SVGs below. Theming rule: NO hex in src/ — only
// semantic fill-retro-*/stroke-retro-* tokens, tint washes, thin strokes.
import { useGameArtStyle } from '../lib/gameArtStyle'

const ART_TYPES = new Set([
  'tictactoe', 'sim', 'chomp', 'breakthrough', 'ataxx', 'kamisado', 'onitama', 'quarto',
  'santorini', 'loa', 'yavalath', 'connectfour', 'hangwoman', 'dotsandboxes', 'sos',
  'simon', 'chimp', 'numbermemory', 'reaction', 'aim', 'typing', 'math', 'arrows', 'updraft',
  'pong', 'snake', 'tron', 'sumo', 'spaceduel', 'paint', 'pacmac', 'visualmemory', 'gomoku',
  'reversi', 'chainreaction', 'blockade', 'orderchaos', 'dice', 'hex', 'minesweeper', 'herd',
  'trivia', 'battleship', 'mancala', 'checkers', 'airhockey', 'artillery', 'animalstack',
  'wirecrossed', 'twotruths', 'bluff', 'lanterns', 'docking', 'wavelength', 'fibbage',
  'spyfair', 'headsup', 'chameleon', 'wordduel', 'wordcoop', 'converge', 'wordrace',
  'wordhunt', 'password', 'anagrams', 'hunch', 'pairs', 'sketch', 'codewords', 'justone',
])

const ART_ALIAS = { chainreaction4: 'chainreaction' }

const resolveArt = (type) => ART_ALIAS[type] || type

export function GameArtImg({ type, className }) {
  const t = resolveArt(type)
  if (!ART_TYPES.has(t)) return null
  return (
    <img
      src={`/game-art/${t}.png`}
      alt=""
      aria-hidden="true"
      draggable={false}
      loading="lazy"
      className={className}
    />
  )
}

function TttSoft({ className }) {
  const xs = [29, 48, 67]
  return (
    <svg viewBox="0 0 96 96" className={className} role="img" aria-label="Tic tac toe art">
      <rect x="0" y="0" width="96" height="96" className="fill-retro-card" />
      {/* soft wash behind the winning row */}
      <rect x="14" y="19" width="68" height="19" rx="9.5" className="fill-retro-tint-cta" />
      <g className="stroke-retro-dim" strokeWidth="2.5" strokeLinecap="round">
        <line x1="38" y1="20" x2="38" y2="76" />
        <line x1="58" y1="20" x2="58" y2="76" />
        <line x1="20" y1="38" x2="76" y2="38" />
        <line x1="20" y1="58" x2="76" y2="58" />
      </g>
      <g className="stroke-retro-p1" strokeWidth="4" strokeLinecap="round">
        {xs.map(cx => (
          <g key={cx}>
            <line x1={cx - 5} y1="24" x2={cx + 5} y2="34" />
            <line x1={cx + 5} y1="24" x2={cx - 5} y2="34" />
          </g>
        ))}
      </g>
      <g fill="none" className="stroke-retro-p2" strokeWidth="4">
        <circle cx="29" cy="67" r="6" />
        <circle cx="67" cy="67" r="6" />
      </g>
    </svg>
  )
}

function ConnectFourSoft({ className }) {
  const xs = [28, 42, 56, 70]
  const ys = [40, 54, 68]
  const connected = new Set(['0,2', '1,2', '2,2', '3,2'])
  const soft = new Set(['1,1', '3,1', '2,0'])
  return (
    <svg viewBox="0 0 96 96" className={className} role="img" aria-label="Connect four art">
      <rect x="0" y="0" width="96" height="96" className="fill-retro-card" />
      <rect x="16" y="28" width="64" height="48" rx="12" className="fill-retro-tint-p1" />
      {ys.map((y, r) =>
        xs.map((x, c) => {
          const k = `${c},${r}`
          if (connected.has(k)) {
            return <circle key={k} cx={x} cy={y} r="6" className="fill-retro-cta" />
          }
          if (soft.has(k)) {
            return <circle key={k} cx={x} cy={y} r="6" className="fill-retro-p2" opacity="0.55" />
          }
          return <circle key={k} cx={x} cy={y} r="6" className="fill-retro-card" opacity="0.85" />
        }),
      )}
      <circle cx="60" cy="16" r="5" className="fill-retro-cta" opacity="0.6" />
    </svg>
  )
}

function PongSoft({ className }) {
  return (
    <svg viewBox="0 0 96 96" className={className} role="img" aria-label="Pong art">
      <rect x="0" y="0" width="96" height="96" className="fill-retro-card" />
      <rect x="14" y="28" width="68" height="40" rx="10"
        className="fill-retro-card stroke-retro-border" strokeWidth="2" />
      <line x1="48" y1="33" x2="48" y2="63" className="stroke-retro-dim"
        strokeWidth="2" strokeDasharray="3 4" strokeLinecap="round" />
      <rect x="20" y="40" width="4.5" height="16" rx="2.25" className="fill-retro-p1" />
      <rect x="71.5" y="40" width="4.5" height="16" rx="2.25" className="fill-retro-p2" />
      <circle cx="58" cy="48" r="8" className="fill-retro-cta" opacity="0.2" />
      <circle cx="58" cy="48" r="4" className="fill-retro-cta" />
    </svg>
  )
}

const SOFT_COMP = {
  tictactoe: TttSoft,
  connectfour: ConnectFourSoft,
  pong: PongSoft,
}

// Fragment helpers for the rest of the catalog (module-private).
const BG = (c) => <rect x="0" y="0" width="96" height="96" className={c} />
const DT = (x, y, r, c, o = 1) => <circle cx={x} cy={y} r={r} className={c} opacity={o} />
const BX = (x, y, w, h, r, c, o = 1) => <rect x={x} y={y} width={w} height={h} rx={r} className={c} opacity={o} />
const LN = (x1, y1, x2, y2, c, w = 3, dash) => (
  <line x1={x1} y1={y1} x2={x2} y2={y2} className={c} strokeWidth={w}
    strokeLinecap="round" {...(dash ? { strokeDasharray: dash } : {})} />
)
const PG = (points, c) => <polygon points={points} className={c} />

