export function GameArtSvg({ type, className }) {
  const t = resolveArt(type)
  if (!ART_TYPES.has(t)) return null
  const Comp = SOFT_COMP[t]
  if (Comp) return <Comp className={className} />
  return (
    <svg viewBox="0 0 96 96" className={className} role="img" aria-hidden="true">
      {SOFT_FRAG[t]}
    </svg>
  )
}

export function GameArt({ type, className }) {
  const style = useGameArtStyle()
  // ICONS: the original mono icon underneath is the look — render nothing.
  if (style === 'icons') return null
  const t = resolveArt(type)
  if (!ART_TYPES.has(t)) return null
  return style === 'svg'
    ? <GameArtSvg type={type} className={className} />
    : <GameArtImg type={type} className={className} />
}
